package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"net/http"
	"sync"
	"sync/atomic"
	"time"

	"golang.org/x/crypto/bcrypt"
)

// RateLimiter implements a token bucket algorithm for API protection
type RateLimiter struct {
	tokens    uint32 // available tokens
	maxTokens uint32
	refillRate uint32
	lastRefill int64
	mu         sync.Mutex
}

func NewRateLimiter(max, refillRate uint32) *RateLimiter {
	return &RateLimiter{
		tokens:     max,
		maxTokens:  max,
		refillRate: refillRate,
		lastRefill: time.Now().UnixNano(),
	}
}

// refill adds tokens based on elapsed time
func (rl *RateLimiter) refill() {
	now := time.Now().UnixNano()
	elapsed := now - atomic.LoadInt64(&rl.lastRefill)
	newTokens := uint32(elapsed / int64(time.Second)) * rl.refillRate
	if newTokens > 0 {
		current := atomic.LoadUint32(&rl.tokens)
		updated := current + newTokens
		if updated > rl.maxTokens {
			updated = rl.maxTokens
		}
		atomic.StoreUint32(&rl.tokens, updated)
		atomic.StoreInt64(&rl.lastRefill, now)
	}
}

// consume attempts to consume one token, returns true if allowed
func (rl *RateLimiter) consume() bool {
	rl.refill()
	// Atomically decrement tokens
	for {
		current := atomic.LoadUint32(&rl.tokens)
		// If current is 0, subtracting 1 would underflow for uint32
		// but we check after the CAS to handle concurrent access
		newVal := current - 1
		if atomic.CompareAndSwapUint32(&rl.tokens, current, newVal) {
			// Check if we underflowed (concurrent drain)
			if newVal > rl.maxTokens {
				// Underflow detected, restore and deny
				atomic.StoreUint32(&rl.tokens, 0)
				return false
			}
			return true
		}
	}
}

// Per-IP rate limiters
var (
	limiters   = make(map[string]*RateLimiter)
	limitersMu sync.RWMutex
)

func getLimiter(ip string) *RateLimiter {
	limitersMu.RLock()
	rl, exists := limiters[ip]
	limitersMu.RUnlock()
	if exists {
		return rl
	}
	limitersMu.Lock()
	defer limitersMu.Unlock()
	// Double-check after acquiring write lock
	if rl, exists = limiters[ip]; exists {
		return rl
	}
	// Allow 5 requests per second for password reset
	rl = NewRateLimiter(5, 5)
	limiters[ip] = rl
	return rl
}

// User store
type User struct {
	Email        string
	PasswordHash []byte
	ResetToken   string
	ResetExpiry  time.Time
}

var (
	users   = make(map[string]*User)
	usersMu sync.RWMutex
)

func generateToken() (string, error) {
	b := make([]byte, 32)
	_, err := rand.Read(b)
	if err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

// handlePasswordResetRequest initiates a password reset
func handlePasswordResetRequest(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	ip := r.RemoteAddr
	rl := getLimiter(ip)
	if !rl.consume() {
		http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
		return
	}

	email := r.FormValue("email")
	if email == "" {
		http.Error(w, "Email required", http.StatusBadRequest)
		return
	}

	usersMu.RLock()
	user, exists := users[email]
	usersMu.RUnlock()

	// Always return success to prevent email enumeration
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "If the email exists, a reset link has been sent.")

	if !exists {
		return
	}

	token, err := generateToken()
	if err != nil {
		return
	}

	usersMu.Lock()
	user.ResetToken = token
	user.ResetExpiry = time.Now().Add(15 * time.Minute)
	usersMu.Unlock()

	// In production, send email with token
	_ = token
}

// handlePasswordReset completes the password reset
func handlePasswordReset(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	ip := r.RemoteAddr
	rl := getLimiter(ip)
	if !rl.consume() {
		http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
		return
	}

	token := r.FormValue("token")
	newPassword := r.FormValue("password")

	if token == "" || newPassword == "" {
		http.Error(w, "Token and password required", http.StatusBadRequest)
		return
	}

	if len(newPassword) < 8 {
		http.Error(w, "Password must be at least 8 characters", http.StatusBadRequest)
		return
	}

	usersMu.RLock()
	var targetUser *User
	for _, u := range users {
		if u.ResetToken != "" && u.ResetToken == token {
			if time.Now().Before(u.ResetExpiry) {
				targetUser = u
			}
			break
		}
	}
	usersMu.RUnlock()

	if targetUser == nil {
		http.Error(w, "Invalid or expired token", http.StatusBadRequest)
		return
	}

	hash, err := bcrypt.GenerateFromPassword([]byte(newPassword), bcrypt.DefaultCost)
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}

	usersMu.Lock()
	targetUser.PasswordHash = hash
	targetUser.ResetToken = ""
	targetUser.ResetExpiry = time.Time{}
	usersMu.Unlock()

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Password reset successful")
}

func main() {
	// Seed a test user
	hash, _ := bcrypt.GenerateFromPassword([]byte("testpassword123"), bcrypt.DefaultCost)
	users["admin@example.com"] = &User{
		Email:        "admin@example.com",
		PasswordHash: hash,
	}

	http.HandleFunc("/reset-request", handlePasswordResetRequest)
	http.HandleFunc("/reset", handlePasswordReset)
	http.ListenAndServe(":8080", nil)
}
